  "hypothesis": "Replacing single-cell transport with geometrically increasing, integer-valued packet transport will escape the smoothing plateau and find a verified improvement of at least 1e-5.",
  "rationale": "The previous search mainly tested fractional mixtures of adjacent cells, which can blur the fine comb before changing its topology. Composing nearest-neighbor moves into integer displacements preserves sharp packet structure at the ray endpoint, while retaining conservative transport, exact quadratic convolution along each ray, and verification against the warm start.",
  "source": "import time
import numpy as np
from scipy.fft import rfft, irfft, next_fast_len
from scipy.signal import oaconvolve

PARAMS = {
    'directions': (24, 4, 80),
    'support_threshold': (1e-12, 1e-16, 1e-7, 'log'),
    'max_transport': (1.0, 0.05, 1.0),
    'reach_fraction': (0.25, 0.015625, 2.0, 'log'),
}


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + 0.70 * budget_s
    rng = np.random.default_rng(seed)
    if init is None:
        original = {'values': np.linspace(0.2, 1.0, 512).tolist()}
    elif 'values' in init:
        original = init
    else:
        original = {'values': init['samples']}
    raw = np.maximum(np.asarray(original['values'], dtype=np.float64), 0.0)
    n = len(raw)
    if n < 3 or not np.max(raw) > 0:
        return original

    def exact(x):
        cc = oaconvolve(x, x, mode='full')
        xx = np.linspace(-0.5, 0.5, len(cc) + 2)
        dx = np.diff(xx)
        yy = np.concatenate(([0.0], cc, [0.0]))
        numerator = float(np.sum((dx / 3.0) *
                          (yy[:-1]**2 + yy[:-1]*yy[1:] + yy[1:]**2)))
        denominator = (np.sum(np.abs(cc)) / (len(cc) + 1)) * np.max(np.abs(cc))
        return float(numerator / denominator)

    baseline = exact(raw)
    f = raw / np.max(raw)
    del raw
    m = 2*n - 1
    size = next_fast_len(m)

    def metric(cc):
        return float((2*np.sum(cc*cc) + np.sum(cc[:-1]*cc[1:])) /
                     (3*np.sum(np.abs(cc))*np.max(np.abs(cc))))

    def geometry(x):
        occupied = x > float(params['support_threshold'])
        changes = np.diff(np.concatenate(([False], occupied, [False])).astype(np.int8))
        starts = np.flatnonzero(changes == 1)
        ends = np.flatnonzero(changes == -1)
        lengths = ends - starts
        ix = np.flatnonzero(occupied)
        centers = np.repeat((starts + ends - 1)*0.5, lengths)
        halves = np.repeat(np.maximum((lengths - 1)*0.5, 1.0), lengths)
        local = np.clip((ix - centers)/halves, -1.0, 1.0)
        position = ix.astype(np.float64)/max(1, n-1)
        # Use packet centers for translations: all cells in a packet agree.
        packet_position = centers/max(1, n-1)
        width = float(np.median(lengths)) if len(lengths) else 1.0
        return ix, local, position, packet_position, width

    if time.monotonic() >= deadline - 4:
        return original
    ff = rfft(f, size, workers=1)
    c = irfft(ff*ff, size, workers=1)[:m].copy()
    current = metric(c)
    best = None
    best_estimate = current
    ix, local, position, packet_position, width = geometry(f)
    if len(ix) == 0:
        return original
    initial_width = width
    transport_time = 0.75

    for iteration in range(int(params['directions'])):
        if time.monotonic() >= deadline - max(3.0, 3.5*transport_time):
            break
        tick = time.monotonic()
        family = iteration % 12
        if family == 0:
            field = local.copy()
        elif family == 1:
            field = -local
        elif family == 2:
            field = np.ones(len(ix))
        elif family == 3:
            field = 2*packet_position - 1
        elif family == 4:
            field = -(2*packet_position - 1)
        elif family == 5:
            field = local*(2*position - 1)
        elif family == 6:
            field = -local*(2*position - 1)
        elif family == 7:
            field = np.sin(2*np.pi*packet_position)
        elif family == 8:
            field = -np.sin(2*np.pi*packet_position)
        elif family == 9:
            field = local*np.cos(2*np.pi*position)
        elif family == 10:
            field = -local*np.cos(2*np.pi*position)
        else:
            field = np.zeros(len(ix))
            for frequency in range(1, 5):
                if time.monotonic() >= deadline - 3:
                    break
                field += rng.normal()*np.sin(frequency*np.pi*packet_position + rng.uniform(0, 2*np.pi))
            field /= max(1.0, float(np.max(np.abs(field))))
        if iteration >= 12:
            field *= -1

        # Compose conservative nearest-neighbor hops before mixing along
        # the ray. Integer destinations keep the endpoint comb sharp.
        level = (iteration // 3) % 4
        base_reach = max(2.0, initial_width*float(params['reach_fraction']))
        radius = min(max(2, n//128), max(2, int(round(base_reach * (2.0**level)))))
        displacement = np.rint(radius*field).astype(np.int64)
        target = np.clip(ix + displacement, 0, n-1)
        delta = np.bincount(target, weights=f[ix], minlength=n)
        delta[ix] -= f[ix]
        del target, displacement, field
        if not np.any(delta):
            continue
        if time.monotonic() >= deadline - 3:
            break
        zz = rfft(delta, size, workers=1)
        linear = irfft(2*ff*zz, size, workers=1)[:m].copy()
        quadratic = irfft(zz*zz, size, workers=1)[:m].copy()
        chosen = 0.0
        chosen_score = current
        max_step = float(params['max_transport'])
        for fraction in (1.0, 0.25, 0.0625, 0.015625, 0.00390625, 0.000244140625, 0.0000152587890625):
            if time.monotonic() >= deadline - 2:
                break
            alpha = max_step*fraction
            value = metric(c + alpha*linear + alpha*alpha*quadratic)
            if value > chosen_score + 3e-15:
                chosen, chosen_score = alpha, value
        if chosen:
            lo, hi = chosen/4, min(max_step, chosen*4)
            for refinement in range(5):
                if time.monotonic() >= deadline - 2:
                    break
                a = lo + (hi-lo)/3
                b = hi - (hi-lo)/3
                va = metric(c + a*linear + a*a*quadratic)
                vb = metric(c + b*linear + b*b*quadratic)
                if va > chosen_score:
                    chosen, chosen_score = a, va
                if vb > chosen_score:
                    chosen, chosen_score = b, vb
                if va < vb:
                    lo = a
                else:
                    hi = b
            f = np.maximum(f + chosen*delta, 0.0)
            ff = ff + chosen*zz
            c = c + chosen*linear + chosen*chosen*quadratic
            current = chosen_score
            if current > best_estimate:
                best_estimate = current
                best = f.copy()
        del delta, linear, quadratic, zz
        transport_time = 0.6*transport_time + 0.4*(time.monotonic()-tick)
        if chosen and time.monotonic() < deadline - 4:
            ix, local, position, packet_position, width = geometry(f)

    if best is not None and time.monotonic() < start + 0.82*budget_s:
        score = exact(best)
        if score > baseline:
            return {'samples': best.tolist()}
    return original
